{
  "name": "@umami/cli",
  "version": "0.2.0",
  "description": "Umami command line interface",
  "author": "Mike Cao <mike@mikecao.com>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/umami-software/cli"
  },
  "bugs": {
    "url": "https://github.com/umami-software/cli"
  },
  "homepage": "https://github.com/umami-software/cli#readme",
  "main": "index.js",
  "bin": {
    "umami": "cli.js"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "dev": "rollup -c rollup.config.js --watch",
    "build": "rollup -c rollup.config.js"
  },
  "dependencies": {
    "dotenv": "^8.2.0",
    "terminal-kit": "^1.42.0",
    "yargs": "^15.4.1"
  },
  "devDependencies": {
    "@rollup/plugin-commonjs": "^14.0.0",
    "eslint": "^7.6.0",
    "eslint-config-prettier": "^6.11.0",
    "eslint-plugin-prettier": "^3.1.3",
    "prettier": "^2.0.5",
    "prettier-eslint": "^11.0.0",
    "rollup": "^2.23.1",
    "rollup-plugin-hashbang": "^2.2.2",
    "rollup-plugin-terser": "^7.0.0"
  }
}

#!/usr/bin/env node

import 'dotenv/config';
import yargs from 'yargs';

const cli = yargs
  .scriptName('umami')
  .usage('$0 <cmd> [args]')
  .alias('v', 'version')
  .alias('h', 'help');

cli.command('config', 'Configures umami', {}, argv => {
  console.log('yo', argv);
});

cli.help(true).argv;

import 'dotenv/config';
import hashbang from 'rollup-plugin-hashbang';
import commonjs from '@rollup/plugin-commonjs';

export default {
  input: 'index.js',
  output: {
    file: 'cli.js',
    format: 'cjs',
  },
  plugins: [
    hashbang(),
    commonjs({
      include: 'node_modules/**',
    }),
  ],
  external: ['yargs', 'chalk', 'dotenv/config', '@prisma/client'],
};
